import XCTest
@testable import ManhuntCrews

/// The app's Live Activity mapping must equal the server's (ADR 0017): local updates and
/// ActivityKit pushes then carry the same content and never fight over the Lock Screen.
/// shared/fixtures/live-activity.json is generated by
/// backend/tests/unit/liveActivity.contract.test.ts from real rendered views.
final class LiveActivityContractTests: XCTestCase {
    private struct Fixture: Decodable {
        struct Case: Decodable {
            var name: String
            var clockOffsetMs: Double
            var view: SessionViewDoc
            var attributes: RoundActivityAttributes?
            var state: RoundActivityAttributes.ContentState?
            var staleDate: Double?
        }
        var cases: [Case]
    }

    private func fixture() throws -> Fixture {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("shared/fixtures/live-activity.json")
        let data = try Data(contentsOf: url)
        // Views decode like API responses; the expected attributes/state decode the way
        // ActivityKit decodes a push: a plain JSONDecoder with default strategies.
        struct Raw: Decodable { var cases: [RawCase] }
        struct RawCase: Decodable {
            var name: String
            var clockOffsetMs: Double
            var attributes: RoundActivityAttributes?
            var state: RoundActivityAttributes.ContentState?
            var staleDate: Double?
        }
        struct Views: Decodable { struct V: Decodable { var view: SessionViewDoc }; var cases: [V] }
        let raw = try JSONDecoder().decode(Raw.self, from: data)
        let views = try JSONCoding.decoder.decode(Views.self, from: data)
        XCTAssertFalse(raw.cases.isEmpty)
        return Fixture(cases: zip(raw.cases, views.cases).map { r, v in
            .init(name: r.name, clockOffsetMs: r.clockOffsetMs, view: v.view, attributes: r.attributes, state: r.state, staleDate: r.staleDate)
        })
    }

    func testMappingMatchesTheServer() throws {
        for c in try fixture().cases {
            XCTAssertEqual(RoundActivityContent.attributes(for: c.view), c.attributes, c.name)
            let state = c.view.round.flatMap { RoundActivityContent.state(for: $0, clockOffsetMs: c.clockOffsetMs) }
            XCTAssertEqual(state, c.state, c.name)
            XCTAssertEqual(state?.staleDate, c.staleDate, c.name)
        }
    }

    func testEveryPhaseIsCovered() throws {
        let phases = Set(try fixture().cases.compactMap { $0.state?.phase })
        XCTAssertEqual(phases, [.HEAD_START, .CHASE, .CAPTURE_PENDING, .PAUSED, .ENDED])
    }

    func testEncodedStateUsesTheServerWireKeys() throws {
        let c = try XCTUnwrap(try fixture().cases.first { $0.state?.phase == .CHASE })
        let json = try JSONSerialization.jsonObject(with: JSONEncoder().encode(c.state!)) as! [String: Any]
        XCTAssertEqual(Set(json.keys).subtracting(["pausedPhase", "headStartEndsAt", "headStartRemaining", "chaseElapsed", "claim", "outcome"]),
                       ["phase", "safetyPause", "chaseStartedAt", "nextPingAt", "nextPingIndex", "timeCapAt", "lastPing", "pingWaiting"])
        // Plain epoch seconds — not Date's default (seconds since 2001).
        XCTAssertEqual(json["chaseStartedAt"] as? Double, c.state!.chaseStartedAt)
    }
}

final class LiveActivityTextTests: XCTestCase {
    private typealias S = RoundActivityAttributes.ContentState

    private func state(_ phase: RoundActivityAttributes.Phase, _ edit: (inout S) -> Void = { _ in }) -> S {
        var s = S(phase: phase, pausedPhase: nil, safetyPause: false, headStartEndsAt: nil, headStartRemaining: nil, chaseStartedAt: nil, chaseElapsed: nil,
                  nextPingAt: nil, nextPingIndex: 0, timeCapAt: nil, lastPing: nil, pingWaiting: false, claim: nil, outcome: nil)
        edit(&s)
        return s
    }

    func testTitlesMatchThePhaseBanner() {
        XCTAssertEqual(RoundActivityText.title(state(.HEAD_START), role: .HIDING), "Head Start · Hiding")
        XCTAssertEqual(RoundActivityText.title(state(.CHASE), role: .SEEKING), "Chase · Seeking")
        XCTAssertEqual(RoundActivityText.title(state(.CAPTURE_PENDING), role: .HIDING), "Catch Pending · Hiding")
        XCTAssertEqual(RoundActivityText.title(state(.PAUSED) { $0.safetyPause = true }, role: .HIDING), "Safety Pause")
        XCTAssertEqual(RoundActivityText.title(state(.ENDED) { $0.outcome = .init(result: .TIMED_OUT, creditCrews: []) }, role: .HIDING), "Not Caught")
    }

    func testRoleIsASymbolAndAWordNeverAColour() {
        XCTAssertEqual(RoundActivityText.symbol(state(.CHASE), role: .HIDING), "eye.slash.fill")
        XCTAssertEqual(RoundActivityText.symbol(state(.CHASE), role: .SEEKING), "binoculars.fill")
        XCTAssertEqual(RoundActivityText.symbol(state(.PAUSED) { $0.safetyPause = true }, role: .SEEKING), "exclamationmark.octagon.fill")
        XCTAssertEqual(RoundActivityText.symbol(state(.CAPTURE_PENDING), role: .HIDING), "camera.fill")
    }

    func testOutcomeIsAttributedToCrewsNotPeople() {
        let caught = state(.ENDED) { $0.chaseElapsed = 754; $0.outcome = .init(result: .CAUGHT, creditCrews: ["B"]) }
        XCTAssertEqual(RoundActivityText.detail(caught, role: .HIDING, crew: "A"), "Found after 12:34.")
        XCTAssertEqual(RoundActivityText.detail(caught, role: .SEEKING, crew: "B"), "Your crew made the catch at 12:34.")
        XCTAssertEqual(RoundActivityText.detail(caught, role: .SEEKING, crew: "C"), "Caught by another crew at 12:34.")
    }

    func testClaimWording() {
        let pending = state(.CAPTURE_PENDING) { $0.claim = .init(crew: "B", expiresAt: 100) }
        XCTAssertEqual(RoundActivityText.detail(pending, role: .HIDING, crew: "A"), "Review the catch photo.")
        XCTAssertEqual(RoundActivityText.detail(pending, role: .SEEKING, crew: "B"), "Hiders are reviewing your catch. Clock frozen.")
        XCTAssertEqual(RoundActivityText.detail(pending, role: .SEEKING, crew: "C"), "Another crew claims a catch. Clock frozen.")
    }

    func testStaleDateFollowsTheNextExpectedUpdate() {
        XCTAssertEqual(state(.HEAD_START) { $0.headStartEndsAt = 1000 }.staleDate, 1090)
        XCTAssertEqual(state(.CHASE) { $0.nextPingAt = 2000; $0.timeCapAt = 1500 }.staleDate, 1590)
        XCTAssertNil(state(.CHASE) { $0.nextPingAt = 2000; $0.pingWaiting = true }.staleDate)
        XCTAssertNil(state(.PAUSED).staleDate)
    }

    #if canImport(UIKit)
    func testTappingOpensTheNight() {
        let a = RoundActivityAttributes(sessionId: "s1", roundId: "r1", roundIndex: 2, role: .SEEKING, crew: "B", crewName: "Hounds")
        XCTAssertEqual(DeepLink(url: RoundActivityText.url(a)), .round(sessionId: "s1"))
    }
    #endif
}
